#if defined(__AVX512F__)
#define VL 16
#define MR 8
#else
#define VL 8
#define MR 6
#endif
#define NR (2 * VL)
#define KC 256
#define MC (MR * 16)
#define NCMAX 4096
#define JCHUNK (NR * 4)

typedef float vf __attribute__((vector_size(VL * 4), aligned(VL * 4)));
typedef float vfu __attribute__((vector_size(VL * 4), aligned(4)));

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int first)
{
    vf acc[MR][2];
#pragma GCC unroll 16
    for (int i = 0; i < MR; i++) {
        acc[i][0] = (vf){0};
        acc[i][1] = (vf){0};
    }
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VL);
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            float ai = a[i];
            acc[i][0] += ai * b0;
            acc[i][1] += ai * b1;
        }
        a += MR;
        b += NR;
    }
    if (first) {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) = acc[i][0];
            *(vfu *)(c + i * ldc + VL) = acc[i][1];
        }
    } else {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) += acc[i][0];
            *(vfu *)(c + i * ldc + VL) += acc[i][1];
        }
    }
}

static void pack_a(const float *A, int n, int i0, int mc, int p0, int kc, float *ap)
{
    for (int p = 0; p < mc; p += MR) {
        int mr = mc - p < MR ? mc - p : MR;
        for (int k = 0; k < kc; k++) {
            int i;
            for (i = 0; i < mr; i++)
